import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Trash2, CheckCircle, AlertCircle } from 'lucide-react';

// The same image dictionary from your store to keep images consistent
const medicineImages = {
  "Paracetamol": "https://images.unsplash.com/photo-1607619056574-7b8d3ee536b2?w=400&q=80",
  "Amoxicillin": "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=400&q=80",
  "Vitamin C": "https://images.unsplash.com/photo-1582436855071-77bba6632402?w=400&q=80",
  "Cough Syrup": "https://images.unsplash.com/photo-1584017911766-d451b3d0e843?w=400&q=80",
  "Ibuprofen": "https://images.unsplash.com/photo-1550989460-0adf9ea622e2?w=400&q=80",
  "Digital Thermometer": "https://images.unsplash.com/photo-1584362917165-526a968579e8?w=400&q=80",
  "First Aid Kit": "https://images.unsplash.com/photo-1603398938378-e54eab446dde?w=400&q=80",
  "Antacid Tablets": "https://images.unsplash.com/photo-1628771065518-0d82f1938462?w=400&q=80",
  "Allergy Relief": "https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=400&q=80",
  "Eye Drops": "https://images.unsplash.com/photo-1618355635391-7f8e815e1bc6?w=400&q=80"
};

const defaultImage = "https://images.unsplash.com/photo-1550572017-ed3c2df28330?w=400&q=80";

function Cart({ cart, removeFromCart, user, placeOrder }) {
  const [isProcessing, setIsProcessing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const total = cart.reduce((sum, item) => sum + parseFloat(item.price), 0);

  const handleCheckout = () => {
    if (!user) {
      setError('Please log in or create an account to proceed with checkout.');
      return;
    }
    
    setIsProcessing(true);
    setError('');
    
    setTimeout(() => {
      setIsProcessing(false);
      setSuccess(true);
      placeOrder(total);
    }, 1500);
  };

  if (success) {
    return (
      <div className="max-w-lg mx-auto mt-16 p-8 bg-white rounded-2xl shadow-lg text-center border border-green-100">
        <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-6">
          <CheckCircle size={40} className="text-green-600" />
        </div>
        <h2 className="text-3xl font-bold text-gray-900 mb-2">Order Confirmed!</h2>
        <p className="text-gray-600 mb-8">Thank you for your purchase. Your medicines are being prepared for dispatch.</p>
        <button 
          onClick={() => navigate('/profile')}
          className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-blue-700 transition w-full"
        >
          View Order History
        </button>
      </div>
    );
  }

  if (cart.length === 0) {
    return <div className="text-center mt-20 text-2xl font-bold text-gray-500">Your cart is empty.</div>;
  }

  return (
    <div className="max-w-4xl mx-auto mt-10 bg-white p-8 rounded-lg shadow-md border border-gray-100">
      <h2 className="text-3xl font-bold mb-6 text-gray-800 border-b pb-4">Shopping Cart</h2>
      
      <div className="space-y-4">
        {cart.map((item, index) => (
          <div key={index} className="flex justify-between items-center bg-gray-50 p-4 rounded border hover:shadow-sm transition-shadow">
            
            {/* Added a flex container to hold the image and text side-by-side */}
            <div className="flex items-center">
              <img 
                src={medicineImages[item.name.trim()] || defaultImage} 
                alt={item.name} 
                className="w-16 h-16 object-cover rounded-md border border-gray-200 mr-4 shadow-sm"
              />
              <div>
                <h3 className="text-xl font-bold text-gray-800">{item.name}</h3>
                <p className="text-gray-500 font-medium">${parseFloat(item.price).toFixed(2)}</p>
              </div>
            </div>
            
            <button 
              onClick={() => removeFromCart(index)}
              className="text-red-500 hover:text-red-700 bg-red-50 hover:bg-red-100 p-2 rounded transition-colors"
            >
              <Trash2 size={20} />
            </button>
          </div>
        ))}
      </div>

      <div className="mt-8 pt-6 border-t">
        <div className="flex justify-between items-center mb-6">
          <span className="text-2xl font-bold text-gray-800">Total:</span>
          <span className="text-3xl font-bold text-blue-600">${total.toFixed(2)}</span>
        </div>

        {error && (
          <div className="mb-4 p-4 bg-red-50 text-red-600 rounded-lg flex items-center border border-red-100">
            <AlertCircle size={20} className="mr-2 flex-shrink-0" />
            <span>{error} <button onClick={() => navigate('/login')} className="underline font-bold">Log in here</button>.</span>
          </div>
        )}
        
        <button 
          onClick={handleCheckout}
          disabled={isProcessing}
          className={`w-full py-3 rounded-lg text-xl font-bold text-white transition ${isProcessing ? 'bg-blue-400 cursor-not-allowed' : 'bg-green-500 hover:bg-green-600 shadow-md'}`}
        >
          {isProcessing ? 'Processing Payment...' : 'Proceed to Checkout'}
        </button>
      </div>
    </div>
  );
}

export default Cart;
